import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";

export default function ListarUsuarios() {
  const [usuarios, setUsuarios] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    axios.get("http://localhost:3001/usuarios")
      .then(res => setUsuarios(res.data))
      .catch(err => console.error("Erro ao carregar usuários:", err));
  }, []);

  return (
    <div className="container mt-5">
      {/* Botão cadastrar no topo */}
      <div className="d-flex justify-content-end mb-3">
        <button className="btn btn-success" onClick={() => navigate("/cadastrar")}>
          Cadastrar Novo
        </button>
      </div>

      {/* Tabela */}
      <div className="table-responsive">
        <table className="table table-striped table-bordered text-center align-middle">
          <thead className="table-dark">
            <tr>
              <th>Nome</th>
              <th>Idade</th>
              <th>Bairro</th>
              <th>Estado</th>
              <th>Foto</th>
              <th>Ações</th>
            </tr>
          </thead>
          <tbody>
            {usuarios.map((user) => (
              <tr key={user.id}>
                <td>{user.nome}</td>
                <td>{user.idade}</td>
                <td>{user.bairro}</td>
                <td>{user.estado}</td>
                <td>
                  {user.imagem ? (
                    <img
                      src={`http://localhost:3001${user.imagem}`}
                      alt="Foto"
                      style={{ width: 40, height: 40, borderRadius: "50%", objectFit: "cover" }}
                    />
                  ) : (
                    "Sem foto"
                  )}
                </td>
                <td>
                  <button className="btn btn-info btn-sm me-2" onClick={() => navigate(`/usuarios/${user.id}`)}>
                    Ver
                  </button>
                  <button className="btn btn-warning btn-sm" onClick={() => navigate(`/editar/${user.id}`)}>
                    Editar
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
